// Author: MiYu. Deferred live checks exercise source mobility abilities with the shared stealth terrain fixture.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=4)throw std::runtime_error("Usage: war3_mobility_tests <data-root> <stealth-fixture> <windwalk|blink|blink-item|reset-cooldown|mirror>");std::wstring mode=argv[3];if(mode!=L"windwalk" && mode!=L"blink" && mode!=L"blink-item" && mode!=L"reset-cooldown" && mode!=L"mirror")throw std::runtime_error("Unknown mobility check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto point=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto hero=vm.global("hero");auto u=session.units().at(hero.bits);call("FogEnable",{vm.boolean(false)});call("FogMaskEnable",{vm.boolean(false)});call("SetUnitPathing",{hero,vm.boolean(false)});auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};
        if(mode==L"windwalk"){
            require(call("UnitAddAbility",{hero,type("AOwk")}).bits && call("IssueImmediateOrder",{hero,vm.string("windwalk")}).bits,"Source Wind Walk order was rejected");session.advance(1.5);require(session.unitInvisible(hero.bits) && u->spellMoveFactor()>1.09f && call("GetUnitAbilityLevel",{hero,type("BOwk")}).bits,"Wind Walk did not supply invisibility, movement or source buff");require(call("IssuePointOrder",{hero,vm.string("move"),point(256),point(0)}).bits,"Wind Walk movement order failed");session.advance(1);require(session.unitInvisible(hero.bits),"Movement broke Wind Walk");auto enemy=call("CreateUnit",{call("Player",{vm.integer(1)}),type("hfoo"),point(int(number(u->x)+64)),point(int(number(u->y))),point(0)});require(call("IssueTargetOrder",{hero,vm.string("attack"),enemy}).bits,"Wind Walk attack order was rejected");session.advance(.0625);require(!session.unitInvisible(hero.bits) && u->combat.windup && u->combat.windup->stealthDamage==40 && u->combat.windup->backstab,"Wind Walk attack did not capture source bonus and break stealth");std::cout<<"PASS windwalk_movement_break_and_attack_payload\n";
        }else if(mode==L"reset-cooldown"){
            auto item=call("UnitAddItemById",{hero,type("desc")});require(item.bits && call("UnitAddAbility",{hero,type("AEbl")}).bits,"Cooldown fixture missing item or ability");u->mana=u->maxMana=jass::Real::fromInteger(1000);require(call("UnitUseItemPoint",{hero,item,point(5000),point(0)}).bits,"Blink item order rejected");session.advance(1);require(session.itemCooldown(hero.bits,item.bits)>0,"Blink item cooldown missing");require(call("IssuePointOrder",{hero,vm.string("blink"),point(0),point(0)}).bits,"Hero Blink order rejected");session.advance(1);require(session.spellCooldown(hero.bits,ObjectData::code("AEbl"))>0,"Hero Blink cooldown missing");call("UnitResetCooldown",{hero});require(session.spellCooldown(hero.bits,ObjectData::code("AEbl"))==0 && session.itemCooldown(hero.bits,item.bits)>0,"Unit cooldown reset changed item cooldown");std::cout<<"PASS unit_reset_preserves_item_cooldown\n";
        }else if(mode==L"blink"){
            require(call("UnitAddAbility",{hero,type("AEbl")}).bits,"Source Blink ability was not added");float x=number(u->x),y=number(u->y),mana=number(u->mana);require(!call("IssuePointOrder",{hero,vm.string("blink"),point(int(x)),point(int(y))}).bits,"Zero-distance Blink was accepted");require(call("IssuePointOrder",{hero,vm.string("blink"),point(5000),point(0)}).bits,"Source Blink point order was rejected");session.advance(1);float distance=std::hypot(number(u->x)-x,number(u->y)-y);require(distance>999 && distance<=1000.1f && number(u->mana)<mana-45,"Blink failed to teleport within the source maximum or consume mana");require(!call("IssuePointOrder",{hero,vm.string("blink"),point(0),point(0)}).bits,"Blink ignored cooldown");std::cout<<"PASS blink_zero_distance_maximum_mana_and_cooldown\n";
        }else if(mode==L"blink-item"){
            auto item=call("UnitAddItemById",{hero,type("desc")});require(item.bits && session.itemNeedsPoint(item.bits),"Blink item did not expose a point target");float x=number(u->x),y=number(u->y);require(!call("UnitUseItemPoint",{hero,item,point(int(x)),point(int(y))}).bits,"Blink item accepted zero distance");require(call("UnitUseItemPoint",{hero,item,point(5000),point(0)}).bits,"Blink item point order rejected");session.advance(1);float distance=std::hypot(number(u->x)-x,number(u->y)-y);require(distance>999 && distance<=1000.1f && session.itemCooldown(hero.bits,item.bits)>0,"Blink item did not move or consume cooldown");require(!call("UnitUseItemPoint",{hero,item,point(0),point(0)}).bits,"Blink item ignored cooldown");std::cout<<"PASS blink_item_target_distance_and_cooldown\n";
        }else{
            require(call("UnitAddAbility",{hero,type("AOmi")}).bits && call("IssueImmediateOrder",{hero,vm.string("mirrorimage")}).bits,"Source Mirror Image order was rejected");for(unsigned step=0;step<32 && !u->mirrorImage;++step)session.advance(1./32);require(u->mirrorImage.has_value() && u->hidden(),"Mirror Image did not enter its source animation delay");auto shade=vm.global("shade");require(!session.damageUnit(shade.bits,hero.bits,25,0,26),"Mirror transformation accepted damage");session.advance(1);require(!u->mirrorImage && !u->hidden(),"Mirror transformation did not restore the original");unsigned clones=0;for(auto& [id,clone]:session.units())if(clone->summoner==hero.bits && clone->summonAbility==ObjectData::code("AOmi")){++clones;require(clone->illusion && clone->damageDealt==0 && clone->damageTaken==2 && clone->timedLife && clone->timedLife->buff==ObjectData::code("BOmi"),"Mirror clone lost source identity, damage factors or timed life");}require(clones==1,"Mirror Image source count was not consumed");std::cout<<"PASS mirror_delay_damage_immunity_restore_and_live_clone\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
